-- the rows are a deterministic generated sample (the recipe is
-- tests/fixtures/chinook/tables.janet, seed 20261020). Generated file,
-- do not edit by hand.

CREATE TABLE artist (artistid INTEGER NOT NULL PRIMARY KEY, name VARCHAR);

CREATE TABLE album (albumid INTEGER NOT NULL PRIMARY KEY, title VARCHAR NOT NULL, artistid INTEGER NOT NULL REFERENCES artist (artistid));

CREATE TABLE genre (genreid INTEGER NOT NULL PRIMARY KEY, name VARCHAR);

CREATE TABLE mediatype (mediatypeid INTEGER NOT NULL PRIMARY KEY, name VARCHAR);

CREATE TABLE employee (employeeid INTEGER NOT NULL PRIMARY KEY, lastname VARCHAR NOT NULL, firstname VARCHAR NOT NULL, title VARCHAR, reportsto INTEGER REFERENCES employee (employeeid), birthdate TIMESTAMP, hiredate TIMESTAMP);
CREATE TABLE customer (customerid INTEGER NOT NULL PRIMARY KEY, firstname VARCHAR NOT NULL, lastname VARCHAR NOT NULL, company VARCHAR, address VARCHAR, city VARCHAR, state VARCHAR, country VARCHAR, postalcode VARCHAR, phone VARCHAR, email VARCHAR NOT NULL, supportrepid INTEGER NOT NULL REFERENCES employee (employeeid));

CREATE TABLE invoice (invoiceid INTEGER NOT NULL PRIMARY KEY, customerid INTEGER NOT NULL REFERENCES customer (customerid), invoicedate TIMESTAMP NOT NULL, billingaddress VARCHAR, billingcity VARCHAR, billingstate VARCHAR, billingcountry VARCHAR, billingpostalcode VARCHAR, total NUMERIC(10,2) NOT NULL);

CREATE TABLE track (trackid INTEGER NOT NULL PRIMARY KEY, name VARCHAR NOT NULL, albumid INTEGER REFERENCES album (albumid), mediatypeid INTEGER NOT NULL REFERENCES mediatype (mediatypeid), genreid INTEGER REFERENCES genre (genreid), composer VARCHAR, milliseconds INTEGER NOT NULL, bytes INTEGER, unitprice NUMERIC(10,2) NOT NULL);

CREATE TABLE playlist (playlistid INTEGER NOT NULL PRIMARY KEY, name VARCHAR);

CREATE TABLE playlist_track (playlistid INTEGER NOT NULL REFERENCES playlist (playlistid), trackid INTEGER NOT NULL REFERENCES track (trackid));

